import { test, expect } from '@playwright/test';

test.describe('File Upload - Folder Organisation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/file-upload');
  });

  test('should upload files and organise them into folders', async ({ page }) => {
    // Setup: intercept the API call
    await page.route('**/api/files/upload', (route) => {
      route.continue();
    });

    // Setup: intercept the folder creation API call
    await page.route('**/api/files/create-folder', (route) => {
      route.continue();
    });

    // Upload file
    const fileInput = page.getByLabel('Upload file');
    await fileInput.setInputFiles('playwright/fixtures/sample.pdf');

    // Click upload button
    const uploadButton = page.getByRole('button', { name: /upload/i });
    await uploadButton.click();

    // Wait for upload to complete
    await page.waitForResponse(response => 
      response.url().includes('/api/files/upload') && response.status() === 200
    );

    // Verify file is uploaded and in the correct folder
    const fileItem = page.getByText('sample.pdf');
    await expect(fileItem).toBeVisible();

    const folderName = page.getByText('Documents');
    await expect(folderName).toBeVisible();

    // Verify file is inside the folder
    const folderContainer = page.locator('[data-testid="folder-container"]');
    await expect(folderContainer).toContainText('sample.pdf');

    // Verify file has a folder icon
    const fileIcon = page.locator('[data-testid="file-icon"]');
    await expect(fileIcon).toBeVisible();
  });

  test('should handle multiple file uploads and create multiple folders', async ({ page }) => {
    // Setup: intercept the API call
    await page.route('**/api/files/upload', (route) => {
      route.continue();
    });

    // Upload multiple files
    const fileInput = page.getByLabel('Upload file');
    await fileInput.setInputFiles('playwright/fixtures/sample1.pdf', 'playwright/fixtures/sample2.pdf');

    // Click upload button
    const uploadButton = page.getByRole('button', { name: /upload/i });
    await uploadButton.click();

    // Wait for upload to complete
    await page.waitForResponse(response => 
      response.url().includes('/api/files/upload') && response.status() === 200
    );

    // Verify both files are uploaded
    const file1 = page.getByText('sample1.pdf');
    const file2 = page.getByText('sample2.pdf');
    await expect(file1).toBeVisible();
    await expect(file2).toBeVisible();

    // Verify two folders are created
    const folder1 = page.getByText('Documents');
    const folder2 = page.getByText('Images');
    await expect(folder1).toBeVisible();
    await expect(folder2).toBeVisible();

    // Verify both files are in their respective folders
    const folderContainer = page.locator('[data-testid="folder-container"]');
    await expect(folderContainer).toContainText('sample1.pdf');
    await expect(folderContainer).toContainText('sample2.pdf');
  });
});
